def maxPalindromeProduct(s):
    n = len(s)
    d = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 1 if i > r else min(d[l + r - i], r - i + 1)
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        d[i] = k
        if i + k - 1 > r:
            l, r = i - k + 1, i + k - 1
    end = [1] * n
    start = [1] * n
    for i in range(n):
        e = i + d[i] - 1
        if 2 * d[i] - 1 > end[e]:
            end[e] = 2 * d[i] - 1
        b = i - d[i] + 1
        if 2 * d[i] - 1 > start[b]:
            start[b] = 2 * d[i] - 1
    for i in range(n - 2, -1, -1):
        if end[i + 1] - 2 > end[i]:
            end[i] = end[i + 1] - 2
    for i in range(1, n):
        if start[i - 1] - 2 > start[i]:
            start[i] = start[i - 1] - 2
    pre = end[:]
    for i in range(1, n):
        pre[i] = max(pre[i], pre[i - 1])
    suf = start[:]
    for i in range(n - 2, -1, -1):
        suf[i] = max(suf[i], suf[i + 1])
    return max(pre[i] * suf[i + 1] for i in range(n - 1))
